import{_ as a,c as e,o as t,ag as i}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"PLC-hårdvara och nätverk","description":"","frontmatter":{},"headers":[],"relativePath":"03-konfiguration/plc-hardvara.md","filePath":"03-konfiguration/plc-hardvara.md","lastUpdated":1768315788000}'),n={name:"03-konfiguration/plc-hardvara.md"};function l(o,r,s,g,d,u){return t(),e("div",null,[...r[0]||(r[0]=[i('<h1 id="plc-hardvara-och-natverk" tabindex="-1">PLC-hårdvara och nätverk <a class="header-anchor" href="#plc-hardvara-och-natverk" aria-label="Permalink to &quot;PLC-hårdvara och nätverk&quot;">​</a></h1><p>Efter att du lagt till PLC:n i projektet behöver du konfigurera hårdvaruparametrar och nätverksinställningar. Korrekt konfiguration är avgörande för att PLC:n ska fungera optimalt och kommunicera med andra enheter.</p><h2 id="oppna-hardvarukonfigurationen" tabindex="-1">Öppna hårdvarukonfigurationen <a class="header-anchor" href="#oppna-hardvarukonfigurationen" aria-label="Permalink to &quot;Öppna hårdvarukonfigurationen&quot;">​</a></h2><ol><li>I projektträdet, expandera din PLC</li><li>Dubbelklicka på <strong>Device configuration</strong></li><li>Du ser nu CPU:n och eventuella tilläggsmoduler i grafisk vy</li></ol><h2 id="konfigurera-cpu-egenskaper" tabindex="-1">Konfigurera CPU-egenskaper <a class="header-anchor" href="#konfigurera-cpu-egenskaper" aria-label="Permalink to &quot;Konfigurera CPU-egenskaper&quot;">​</a></h2><h3 id="allmanna-installningar" tabindex="-1">Allmänna inställningar <a class="header-anchor" href="#allmanna-installningar" aria-label="Permalink to &quot;Allmänna inställningar&quot;">​</a></h3><p>Markera CPU:n i device configuration och öppna <strong>Properties</strong> (längst ner):</p><h4 id="system-och-clock-memory" tabindex="-1">System och clock memory <a class="header-anchor" href="#system-och-clock-memory" aria-label="Permalink to &quot;System och clock memory&quot;">​</a></h4><ol><li>Under <strong>General</strong> → <strong>System and clock memory</strong></li><li><strong>Clock memory byte</strong> - Aktivera och välj byte (t.ex. %MB0) <ul><li>Ger dig tillgång till blinksignaler (1Hz, 2Hz, etc.)</li><li>Användbart för blinkande lampor och test</li></ul></li><li><strong>First scan bit</strong> - Biten som är aktiv första cykeln <ul><li>Användbart för initieringsrutiner</li></ul></li></ol><h4 id="startup-efter-stromavbrott" tabindex="-1">Startup efter strömavbrott <a class="header-anchor" href="#startup-efter-stromavbrott" aria-label="Permalink to &quot;Startup efter strömavbrott&quot;">​</a></h4><ol><li>Under <strong>Startup</strong></li><li>Välj beteende vid uppstart: <ul><li><strong>Warm restart</strong> - Behåller remanenta data (rekommenderas)</li><li><strong>Cold restart</strong> - Nollställer allt</li><li><strong>No restart</strong> - Startar inte automatiskt</li></ul></li></ol><h3 id="webserver" tabindex="-1">Webserver <a class="header-anchor" href="#webserver" aria-label="Permalink to &quot;Webserver&quot;">​</a></h3><p>Aktivera den inbyggda webbservern för diagnostik:</p><ol><li>Under <strong>General</strong> → <strong>Web server</strong></li><li>Aktivera &quot;Enable web server on this module&quot;</li><li>Välj säkerhetsalternativ: <ul><li><strong>Allow access only with HTTPS</strong> (rekommenderas för produktion)</li><li>Användarnamn och lösenord kan konfigureras</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Med webbservern kan du öppna diagnostikinformation genom att surfa till PLC:ns IP-adress i en vanlig webbläsare!</p></div><h3 id="protection-security" tabindex="-1">Protection &amp; Security <a class="header-anchor" href="#protection-security" aria-label="Permalink to &quot;Protection &amp; Security&quot;">​</a></h3><p>Skydda ditt program från obehörig åtkomst:</p><ol><li>Under <strong>Protection &amp; Security</strong> → <strong>Connection mechanisms</strong></li><li><strong>Access levels:</strong><ul><li>Full access (read/write)</li><li>Read access</li><li>HMI access</li><li>No access (only after reboot)</li></ul></li><li>Sätt lösenord för varje nivå efter behov</li></ol><h2 id="konfigurera-ethernet-ip-adresser" tabindex="-1">Konfigurera Ethernet/IP-adresser <a class="header-anchor" href="#konfigurera-ethernet-ip-adresser" aria-label="Permalink to &quot;Konfigurera Ethernet/IP-adresser&quot;">​</a></h2><h3 id="profinet-interface" tabindex="-1">PROFINET Interface <a class="header-anchor" href="#profinet-interface" aria-label="Permalink to &quot;PROFINET Interface&quot;">​</a></h3><ol><li>Markera CPU:ns <strong>Ethernet-port</strong> (grön PROFINET-ikon)</li><li>Under <strong>Properties</strong> → <strong>Ethernet addresses</strong></li></ol><h4 id="ip-adress" tabindex="-1">IP-adress <a class="header-anchor" href="#ip-adress" aria-label="Permalink to &quot;IP-adress&quot;">​</a></h4><ul><li><strong>IP address:</strong> <code>192.168.0.10</code> (exempel)</li><li><strong>Subnet mask:</strong> <code>255.255.255.0</code> (standard för Class C)</li><li><strong>Use router:</strong> Aktivera endast om routing behövs</li><li><strong>Router address:</strong> Gateway-adress (om tillämpligt)</li></ul><h4 id="device-name-for-profinet-io" tabindex="-1">Device name (för PROFINET IO) <a class="header-anchor" href="#device-name-for-profinet-io" aria-label="Permalink to &quot;Device name (för PROFINET IO)&quot;">​</a></h4><ul><li>Används för PROFINET IO-devices</li><li>Exempel: <code>plc-main-controller</code></li><li>Viktigt för IO-device-identifiering</li></ul><h3 id="dhcp-vs-statisk-ip" tabindex="-1">DHCP vs Statisk IP <a class="header-anchor" href="#dhcp-vs-statisk-ip" aria-label="Permalink to &quot;DHCP vs Statisk IP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metod</th><th>Fördelar</th><th>Nackdelar</th></tr></thead><tbody><tr><td><strong>Statisk IP</strong></td><td>Enkel, pålitlig, ingen DHCP-server behövs</td><td>Manuell konfiguration</td></tr><tr><td><strong>DHCP</strong></td><td>Automatisk tilldelning</td><td>Kräver DHCP-server, IP kan ändras</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Rekommendation</p><p>Använd <strong>statisk IP</strong> för PLC:er i produktion. DHCP kan användas för test och simulering.</p></div><h2 id="konfigurera-in-och-utgangar" tabindex="-1">Konfigurera in- och utgångar <a class="header-anchor" href="#konfigurera-in-och-utgangar" aria-label="Permalink to &quot;Konfigurera in- och utgångar&quot;">​</a></h2><h3 id="digitala-ingangar-di" tabindex="-1">Digitala ingångar (DI) <a class="header-anchor" href="#digitala-ingangar-di" aria-label="Permalink to &quot;Digitala ingångar (DI)&quot;">​</a></h3><ol><li>Markera en <strong>digital input module</strong> eller inbyggda DI</li><li>Under <strong>Properties</strong> → <strong>Inputs</strong></li><li>Konfigurera per kanal: <ul><li><strong>Input delay</strong> - Filtreringstid för debouncing (standard 0.1-10 ms)</li><li>Viktigt för mekaniska switchar och reläer</li></ul></li></ol><h3 id="digitala-utgangar-dq" tabindex="-1">Digitala utgångar (DQ) <a class="header-anchor" href="#digitala-utgangar-dq" aria-label="Permalink to &quot;Digitala utgångar (DQ)&quot;">​</a></h3><ol><li>Markera <strong>digital output module</strong></li><li>Under <strong>Properties</strong> → <strong>Outputs</strong></li><li>Konfigurera: <ul><li><strong>Reaction to CPU STOP</strong> - Vad händer vid PLC-stopp? <ul><li>Keep last value (behåll)</li><li>Set substitute value (0 eller 1)</li></ul></li><li><strong>Diagnostics</strong> - Aktivera för feldetektering (kortslutning, överbelastning)</li></ul></li></ol><h3 id="analoga-ingangar-ai" tabindex="-1">Analoga ingångar (AI) <a class="header-anchor" href="#analoga-ingangar-ai" aria-label="Permalink to &quot;Analoga ingångar (AI)&quot;">​</a></h3><ol><li>Markera <strong>analog input module</strong></li><li>Under <strong>Properties</strong> → <strong>Inputs</strong></li><li>Konfigurera per kanal: <ul><li><strong>Measurement type:</strong> Voltage (0-10V), Current (4-20mA), Resistance, Thermocouple</li><li><strong>Measurement range:</strong> T.ex. 0-10V, 4-20mA</li><li><strong>Smoothing:</strong> Medelvärdesfilter (None, Weak, Medium, Strong)</li><li><strong>Enable limit monitoring:</strong> Larm vid över-/underskridning</li></ul></li></ol><h3 id="analoga-utgangar-ao" tabindex="-1">Analoga utgångar (AO) <a class="header-anchor" href="#analoga-utgangar-ao" aria-label="Permalink to &quot;Analoga utgångar (AO)&quot;">​</a></h3><ol><li>Markera <strong>analog output module</strong></li><li>Konfigurera: <ul><li><strong>Output type:</strong> Voltage (0-10V) eller Current (4-20mA)</li><li><strong>Reaction to CPU STOP:</strong> Substitute value vid PLC-stopp</li><li><strong>Diagnostics:</strong> Övervaka kabelbr ott och kortslutning</li></ul></li></ol><h2 id="konfigurera-hoghastighetsingangar" tabindex="-1">Konfigurera höghastighetsingångar <a class="header-anchor" href="#konfigurera-hoghastighetsingangar" aria-label="Permalink to &quot;Konfigurera höghastighetsingångar&quot;">​</a></h2><p>För räknare och pulsutgångar:</p><ol><li>Under CPU → <strong>Properties</strong> → <strong>High-speed counters (HSC)</strong></li><li>Aktivera önskade HSC (HSC1, HSC2, etc.)</li><li>Konfigurera: <ul><li><strong>Mode:</strong> Single-phase, Two-phase, A/B counter</li><li><strong>Frequency:</strong> Max frekvens (upp till 100 kHz)</li><li><strong>Hardware inputs:</strong> Vilka ingångar som används</li></ul></li></ol><h2 id="cycle-time-och-watchdog" tabindex="-1">Cycle time och watchdog <a class="header-anchor" href="#cycle-time-och-watchdog" aria-label="Permalink to &quot;Cycle time och watchdog&quot;">​</a></h2><h3 id="cycletid" tabindex="-1">Cycletid <a class="header-anchor" href="#cycletid" aria-label="Permalink to &quot;Cycletid&quot;">​</a></h3><ol><li>Under CPU → <strong>Properties</strong> → <strong>Cycle</strong></li><li><strong>Minimum cycle time:</strong> Minsta cykeltid (standard: 1 ms)</li><li><strong>Maximum cycle time:</strong> Watchdog-gräns (standard: 150 ms) <ul><li>PLC går i STOP om denna överskrids</li></ul></li><li><strong>Scan cycle monitoring time:</strong> Övervaknings-timeout</li></ol><div class="warning custom-block"><p class="custom-block-title">Observera</p><p>Om din cykeltid närmar sig max-värdet, optimera programmet eller öka watchdog-tiden.</p></div><h2 id="kompilera-och-ladda-ner-konfiguration" tabindex="-1">Kompilera och ladda ner konfiguration <a class="header-anchor" href="#kompilera-och-ladda-ner-konfiguration" aria-label="Permalink to &quot;Kompilera och ladda ner konfiguration&quot;">​</a></h2><h3 id="kompilera-hardvaran" tabindex="-1">Kompilera hårdvaran <a class="header-anchor" href="#kompilera-hardvaran" aria-label="Permalink to &quot;Kompilera hårdvaran&quot;">​</a></h3><ol><li>Högerklicka på PLC:n i projektträdet</li><li>Välj <strong>Compile</strong> → <strong>Hardware (rebuild all)</strong></li><li>Kontrollera <strong>Info</strong>-fönstret för fel och varningar</li><li>Åtgärda eventuella fel</li></ol><h3 id="ladda-ner-till-plc" tabindex="-1">Ladda ner till PLC <a class="header-anchor" href="#ladda-ner-till-plc" aria-label="Permalink to &quot;Ladda ner till PLC&quot;">​</a></h3><ol><li>Anslut PC till PLC via Ethernet-kabel</li><li>Klicka på <strong>Online</strong> → <strong>Download to device</strong></li><li>Välj PLC (eller <strong>Show all accessible devices</strong> för att söka)</li><li>Markera vad som ska laddas: <ul><li>Hardware configuration</li><li>PLC program blocks</li><li>HMI</li></ul></li><li>Klicka <strong>Load</strong></li><li>Bekräfta och vänta på överföringen</li><li>PLC startar om och går i RUN-läge</li></ol><h2 id="diagnostik-och-felsokning" tabindex="-1">Diagnostik och felsökning <a class="header-anchor" href="#diagnostik-och-felsokning" aria-label="Permalink to &quot;Diagnostik och felsökning&quot;">​</a></h2><h3 id="onlinevy" tabindex="-1">Onlinevy <a class="header-anchor" href="#onlinevy" aria-label="Permalink to &quot;Onlinevy&quot;">​</a></h3><ol><li>Klicka <strong>Go online</strong> (ikon i verktygsfältet)</li><li>Du ser nu realtidsstatus: <ul><li><strong>Gröna</strong> moduler = OK</li><li><strong>Röda</strong> moduler = Fel</li></ul></li><li>Dubbelklicka på modul för detaljerad diagnostik</li></ol><h3 id="diagnostikbuffert" tabindex="-1">Diagnostikbuffert <a class="header-anchor" href="#diagnostikbuffert" aria-label="Permalink to &quot;Diagnostikbuffert&quot;">​</a></h3><ol><li>PLC → <strong>Online &amp; diagnostics</strong> → <strong>Diagnostics</strong></li><li><strong>Diagnostic buffer</strong> visar alla händelser: <ul><li>Uppstart/stopp</li><li>Kommunikationsfel</li><li>Hårdvarufel</li></ul></li><li>Användbart för felsökning</li></ol><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><p>✅ <strong>Använd konsekvent IP-adressering</strong></p><ul><li>PLC:er: <code>.10-.19</code></li><li>HMI: <code>.20-.29</code></li><li>Frekvensomriktare: <code>.30-.39</code></li></ul><p>✅ <strong>Dokumentera hårdvaruinställningar</strong></p><ul><li>Skriv kommentarer i projektets Properties</li><li>Exportera konfiguration regelbundet</li></ul><p>✅ <strong>Testa webservern</strong></p><ul><li>Öppna <code>http://192.168.0.10</code> (din PLC-IP) i webbläsaren</li><li>Verifiera att diagnostik fungerar</li></ul><p>✅ <strong>Sätt rimliga watchdog-tider</strong></p><ul><li>För enkla program: 150 ms (default)</li><li>För komplexa: 300-500 ms</li></ul><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/36912030" target="_blank" rel="noreferrer">S7-1200 Hardware Configuration</a> - System Manual</li><li><a href="https://support.industry.siemens.com/cs/document/49948856" target="_blank" rel="noreferrer">PROFINET IO Configuration</a> - Profinet Guide</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal S7-1200 hardware configuration&quot;</li><li>YouTube: &quot;TIA Portal IP address setup&quot;</li><li>YouTube: &quot;TIA Portal analog input configuration&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Nu när PLC:n är konfigurerad, fortsätt med <a href="./hmi-installningar.html">HMI-inställningar</a> för att konfigurera din operatörspanel.</p></div>',69)])])}const k=a(n,[["render",l]]);export{h as __pageData,k as default};
